-- ============================================================
-- 14. 생산DB × Python 연동 실습 — 데이터 준비 (PostgreSQL)
--     생산 데이터 + 같은 공장의 인사·근태 데이터
-- ------------------------------------------------------------
-- 가상의 가전 조립공장(냉장고·세탁기·에어컨 3개 라인)의
-- 2026년 10월 생산 실적·불량·비가동·설비 센서 데이터와
-- 현장 직원의 인사·근태·교육 데이터입니다.
-- 실습용 합성 데이터이며 실제 공장 수치가 아닙니다.
--
-- 실행 방법: pgAdmin Query Tool(또는 psql)에서 이 파일 전체를 실행합니다.
--   psql -U postgres -d postgres -f "14. 생산DB_Python연동.sql"
--   (한국어 Windows의 psql에서는 접속한 뒤 \encoding UTF8 을 먼저 입력하고 \i 로 실행합니다)
-- 여러 번 실행해도 됩니다(맨 앞에서 테이블을 지우고 다시 만듭니다).
--
-- 테이블 구성
--   line_master        라인 기준정보            3행
--   equipment_master   설비 기준정보            9행
--   model_master       모델 기준정보            6행
--   production_result  교대별 생산 실적         162행  (일 × 교대 × 라인)
--   defect_log         불량 유형별 수량         380행
--   downtime_log       비가동 기록              203행
--   sensor_hourly      설비 센서 1시간 평균     5832행
--   quality_judgment   Python 판정 결과 기록용  0행 (실습에서 채움)
--   employee_master    현장 직원 기준정보       70행
--   attendance_log     일별 근태                1890행  (직원 × 가동일)
--   training_log       교육 이수 기록           91행  (이수자만 행이 있음)
-- 기간: 2026-10-01 ~ 2026-10-31, 일요일 휴무 (27일)
-- 교대: 주간 08:00~20:00 / 야간 20:00~익일 08:00 (교대당 720분)
-- ============================================================

DROP TABLE IF EXISTS training_log;
DROP TABLE IF EXISTS attendance_log;
DROP TABLE IF EXISTS employee_master;
DROP TABLE IF EXISTS quality_judgment;
DROP TABLE IF EXISTS sensor_hourly;
DROP TABLE IF EXISTS downtime_log;
DROP TABLE IF EXISTS defect_log;
DROP TABLE IF EXISTS production_result;
DROP TABLE IF EXISTS model_master;
DROP TABLE IF EXISTS equipment_master;
DROP TABLE IF EXISTS line_master;

-- 1) 라인 기준정보
CREATE TABLE line_master (
    line_code       VARCHAR(5)   PRIMARY KEY,
    line_name       VARCHAR(50)  NOT NULL,
    product_group   VARCHAR(20)  NOT NULL,
    plan_per_shift  INTEGER      NOT NULL          -- 교대당 계획 수량
);

-- 2) 설비 기준정보
CREATE TABLE equipment_master (
    equip_code   VARCHAR(10)  PRIMARY KEY,
    line_code    VARCHAR(5)   NOT NULL REFERENCES line_master(line_code),
    equip_name   VARCHAR(50)  NOT NULL,
    process      VARCHAR(20)  NOT NULL             -- 공정
);

-- 3) 모델 기준정보
CREATE TABLE model_master (
    model_code   VARCHAR(10)  PRIMARY KEY,
    model_name   VARCHAR(50)  NOT NULL,
    line_code    VARCHAR(5)   NOT NULL REFERENCES line_master(line_code),
    cycle_sec    INTEGER      NOT NULL             -- 표준 택트타임(초)
);

-- 4) 교대별 생산 실적 : 생산 = 양품 + 불량, 가동 + 비가동 = 720분
CREATE TABLE production_result (
    result_id    INTEGER      PRIMARY KEY,
    work_date    DATE         NOT NULL,
    shift        VARCHAR(5)   NOT NULL CHECK (shift IN ('주간','야간')),
    line_code    VARCHAR(5)   NOT NULL REFERENCES line_master(line_code),
    model_code   VARCHAR(10)  NOT NULL REFERENCES model_master(model_code),
    plan_qty     INTEGER      NOT NULL,
    prod_qty     INTEGER      NOT NULL,
    good_qty     INTEGER      NOT NULL,
    defect_qty   INTEGER      NOT NULL,
    run_min      INTEGER      NOT NULL,
    down_min     INTEGER      NOT NULL,
    CHECK (prod_qty = good_qty + defect_qty)
);

-- 5) 불량 유형별 수량 : 같은 result_id의 qty 합 = production_result.defect_qty
CREATE TABLE defect_log (
    defect_id    INTEGER      PRIMARY KEY,
    result_id    INTEGER      NOT NULL REFERENCES production_result(result_id),
    defect_type  VARCHAR(20)  NOT NULL,
    qty          INTEGER      NOT NULL
);

-- 6) 비가동 기록 : 설비와 무관한 사유(자재대기 등)는 equip_code가 NULL
CREATE TABLE downtime_log (
    down_id       INTEGER      PRIMARY KEY,
    line_code     VARCHAR(5)   NOT NULL REFERENCES line_master(line_code),
    equip_code    VARCHAR(10)  REFERENCES equipment_master(equip_code),
    work_date     DATE         NOT NULL,
    shift         VARCHAR(5)   NOT NULL,
    start_time    TIMESTAMP    NOT NULL,
    end_time      TIMESTAMP    NOT NULL,
    duration_min  INTEGER      NOT NULL,
    reason        VARCHAR(20)  NOT NULL
);

-- 7) 설비 센서 1시간 평균 : 센서 누락 시 temp_c가 NULL
CREATE TABLE sensor_hourly (
    equip_code      VARCHAR(10)  NOT NULL REFERENCES equipment_master(equip_code),
    measured_at     TIMESTAMP    NOT NULL,
    temp_c          NUMERIC(5,1),
    vibration_mm_s  NUMERIC(5,2),
    PRIMARY KEY (equip_code, measured_at)
);

-- 8) Python에서 계산한 일별 품질 판정을 기록하는 테이블 (처음에는 비어 있음)
CREATE TABLE quality_judgment (
    judge_id      SERIAL       PRIMARY KEY,
    work_date     DATE         NOT NULL,
    line_code     VARCHAR(5)   NOT NULL REFERENCES line_master(line_code),
    defect_rate   NUMERIC(5,2) NOT NULL,           -- 불량률(%)
    judgment      VARCHAR(10)  NOT NULL CHECK (judgment IN ('정상','주의','이상')),
    judged_by     VARCHAR(30)  NOT NULL DEFAULT 'python',
    judged_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (work_date, line_code)
);

COMMENT ON TABLE production_result IS '교대별 생산 실적 (생산=양품+불량)';
COMMENT ON TABLE defect_log        IS '실적별 불량 유형 수량';
COMMENT ON TABLE downtime_log      IS '비가동 기록 (설비무관 사유는 equip_code NULL)';
COMMENT ON TABLE sensor_hourly     IS '설비 센서 1시간 평균';
COMMENT ON TABLE quality_judgment  IS 'Python 판정 결과 기록';

