-- ============================================================
-- 인사·근태 데이터 (같은 공장의 현장 직원, 2026년 10월, 합성 데이터)
-- ============================================================

-- 9) 현장 직원 기준정보 : 10월 한 달 동안 라인·교대조가 고정
CREATE TABLE employee_master (
    emp_no       VARCHAR(5)   PRIMARY KEY,
    emp_name     VARCHAR(20)  NOT NULL,
    line_code    VARCHAR(5)   NOT NULL REFERENCES line_master(line_code),
    shift        VARCHAR(5)   NOT NULL CHECK (shift IN ('주간','야간')),
    job_role     VARCHAR(10)  NOT NULL,             -- 반장, 조립, 검사, 설비보전
    hire_date    DATE         NOT NULL,
    skill_grade  CHAR(1)      NOT NULL CHECK (skill_grade IN ('A','B','C'))   -- A 숙련, B 일반, C 수습(입사 1년 미만)
);

-- 10) 일별 근태 : 직원마다 가동일 하루에 한 행 (근무조의 날짜는 교대 시작일 기준)
CREATE TABLE attendance_log (
    att_id     INTEGER      PRIMARY KEY,
    emp_no     VARCHAR(5)   NOT NULL REFERENCES employee_master(emp_no),
    work_date  DATE         NOT NULL,
    status     VARCHAR(5)   NOT NULL CHECK (status IN ('출근','지각','결근','휴가')),
    UNIQUE (emp_no, work_date)
);

-- 11) 교육 이수 기록 : 이수한 사람만 행이 있음 (미이수자는 행이 없음)
CREATE TABLE training_log (
    training_id     INTEGER      PRIMARY KEY,
    emp_no          VARCHAR(5)   NOT NULL REFERENCES employee_master(emp_no),
    course_name     VARCHAR(30)  NOT NULL,
    completed_date  DATE         NOT NULL
);

COMMENT ON TABLE employee_master IS '현장 직원 기준정보 (라인·교대조·숙련등급)';
COMMENT ON TABLE attendance_log  IS '일별 근태 (출근·지각·결근·휴가)';
COMMENT ON TABLE training_log    IS '교육 이수 기록 (이수자만 행이 있음)';

